            if ((d.presence & 64) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_OUTPUT
            {
                m.Output = new TaskOutput();
                m.Output.Success = d.output.success != 0;
                m.Output.Error = Str(b, d.output.error);
            }
            m.PodHostname = Str(b, d.pod_hostname);
            if ((d.presence & 128) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_RECEIVED_AT
            {
                m.ReceivedAt = new Timestamp();
                m.ReceivedAt.Seconds = d.received_at.seconds;
                m.ReceivedAt.Nanos = d.received_at.nanos;
            }
            if ((d.presence & 256) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_ACQUIRED_AT
            {
                m.AcquiredAt = new Timestamp();
                m.AcquiredAt.Seconds = d.acquired_at.seconds;
                m.AcquiredAt.Nanos = d.acquired_at.nanos;
            }
            if ((d.presence & 512) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_CREATION_TO_END_DURATION
            {
                m.CreationToEndDuration = new Duration();
                m.CreationToEndDuration.Seconds = d.creation_to_end_duration.seconds;
                m.CreationToEndDuration.Nanos = d.creation_to_end_duration.nanos;
            }
            if ((d.presence & 1024) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_PROCESSING_TO_END_DURATION
            {
                m.ProcessingToEndDuration = new Duration();
                m.ProcessingToEndDuration.Seconds = d.processing_to_end_duration.seconds;
                m.ProcessingToEndDuration.Nanos = d.processing_to_end_duration.nanos;
            }
            m.InitialTaskId = Str(b, d.initial_task_id);
            if ((d.presence & 2048) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_RECEIVED_TO_END_DURATION
            {
                m.ReceivedToEndDuration = new Duration();
                m.ReceivedToEndDuration.Seconds = d.received_to_end_duration.seconds;
                m.ReceivedToEndDuration.Nanos = d.received_to_end_duration.nanos;
            }
            if ((d.presence & 4096) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_PROCESSED_AT
            {
                m.ProcessedAt = new Timestamp();
                m.ProcessedAt.Seconds = d.processed_at.seconds;
                m.ProcessedAt.Nanos = d.processed_at.nanos;
            }
            if ((d.presence & 8192) != 0)   // AK_DFIX_TASKDETAILED_PRESENT_FETCHED_AT
            {
                m.FetchedAt = new Timestamp();
                m.FetchedAt.Seconds = d.fetched_at.seconds;
                m.FetchedAt.Nanos = d.fetched_at.nanos;
            }
            m.PayloadId = Str(b, d.payload_id);
            m.CreatedBy = Str(b, d.created_by);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_parent_task_ids(IntPtr ctx, void* obj, long token, ak_span* xs, int n)
    {
        try
        {
            var run = (DecRun2*)obj;
            var t = (ListTasksDetailedResponse)GCHandle.FromIntPtr(run->Target).Target;
            byte* b = run->Buf;
            var lst = t.Tasks[(int)token].ParentTaskIds;
            for (int i = 0; i < n; i++) lst.Add(Str(b, xs[i]));
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

