    /// The map run. It arrives BEFORE `apply_tasks`, so the parent has to be made here
    /// and `apply_tasks` must not replace it. That ordering is not obvious from the
    /// header and is the kind of thing a byte-identity gate does not catch: the re-
    /// encode would still match if the map were dropped on both sides.
    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_options_options(IntPtr ctx, void* obj, long token, ak_dfix_TaskOptionsOptionsEntry* xs, int n)
    {
        try
        {
            var run = (DecRun2*)obj;
            var t = (ListTasksDetailedResponse)GCHandle.FromIntPtr(run->Target).Target;
            byte* b = run->Buf;
            var m = t.Tasks[(int)token];
            m.Options ??= new TaskOptions();
            var mp = m.Options.Options;
            for (int i = 0; i < n; i++) mp[Str(b, xs[i].key)] = Str(b, xs[i].value);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    public ListTasksDetailedResponse Decode(byte[] src, int len)
    {
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun2*)NativeMemory.Alloc((nuint)sizeof(DecRun2));
        }
        Abi.ak_dec_err_reset(_dctx);
        var target = new ListTasksDetailedResponse();
        var h = GCHandle.Alloc(target);
        try
        {
            fixed (byte* b = src)
            {
                _drun->Target = GCHandle.ToIntPtr(h);
                _drun->Buf = b;
                var vt = new ak_dvt_ListTasksDetailedResponse
                {
                    apply = &ApplyRoot,
                    unknown = IntPtr.Zero,
                    unk_tasks = IntPtr.Zero,
                    new_tasks = &NewTask,
                    apply_tasks = &ApplyTask,
                    add_tasks_parent_task_ids = &Add_parent_task_ids,
                    add_tasks_data_dependencies = &Add_data_dependencies,
                    add_tasks_expected_output_ids = &Add_expected_output_ids,
                    add_tasks_retry_of_ids = &Add_retry_of_ids,
                    add_tasks_options_options = &Add_options_options,
                };
                ForwardCalls++;   // ak_decode_*
                ReverseCalls++;   // apply
                int rc = Abi.ak_decode_ListTasksDetailedResponse(_dctx, _drun, b, (nuint)len, &vt);
                if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}");
                int he = Abi.ak_dec_err(_dctx);
                if (he != 0) throw new InvalidOperationException($"host reported {he} through ak_fail");
            }
        }
        finally { h.Free(); }
        // The per-element reverse calls, tallied from the graph that came back
        // rather than predicted: `new` and `apply` per element, plus one run per
        // inner field that actually occurred.
        for (int i = 0; i < target.Tasks.Count; i++)
        {
            ReverseCalls += 2;
            var m = target.Tasks[i];
            if (m.ParentTaskIds.Count != 0) ReverseCalls++;
            if (m.DataDependencies.Count != 0) ReverseCalls++;
            if (m.ExpectedOutputIds.Count != 0) ReverseCalls++;
            if (m.RetryOfIds.Count != 0) ReverseCalls++;
            if (m.Options != null && m.Options.Options.Count != 0) ReverseCalls++;
        }
        return target;
    }

    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_groups != null) { NativeMemory.AlignedFree(_groups); _groups = null; }
        if (_blobs != null) { NativeMemory.AlignedFree(_blobs); _blobs = null; }
        if (_ents != null) { NativeMemory.AlignedFree(_ents); _ents = null; }
        if (_blobOff != null) { NativeMemory.Free(_blobOff); _blobOff = null; }
        if (_blobCnt != null) { NativeMemory.Free(_blobCnt); _blobCnt = null; }
        if (_entOff != null) { NativeMemory.Free(_entOff); _entOff = null; }
        if (_entCnt != null) { NativeMemory.Free(_entCnt); _entCnt = null; }
        if (_staging != null) { NativeMemory.Free(_staging); _staging = null; }
        if (_run != null) { NativeMemory.Free(_run); _run = null; }
        if (_evt != null) { NativeMemory.Free(_evt); _evt = null; }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
